	HevyClientService,
	HevyOperationsService,
	ToolExecutionContextService,
	ToolObserverService,
} from "./effect-services.js";
export {
	createCoreServiceLayer,
	createToolObserverLayer,
	type CoreServiceLayerOptions,
} from "./effect-layer.js";

import { preloadCompactJsonSchema } from "../utils/compact-json-schema.js";
import {
	getRegisteredToolConfig,
	registerToolDefinition,
	type ToolRegistrar,
} from "./define-tool.js";
import { bodyMeasurementToolDefinitions } from "./body-measurements.js";
import { folderToolDefinitions } from "./folders.js";
import { routineToolDefinitions } from "./routines.js";
import { templateToolDefinitions } from "./templates.js";
import { routineDiscoveryToolDefinitions } from "./routine-discovery.js";
import { workflowToolDefinitions } from "./workflows.js";
import { workoutToolDefinitions } from "./workouts.js";
import type { ToolRuntime } from "./tool-runtime.js";

export const hevyToolDefinitions = [
	...workoutToolDefinitions,
	...routineToolDefinitions,
	...templateToolDefinitions,
	...folderToolDefinitions,
	...bodyMeasurementToolDefinitions,
	...workflowToolDefinitions,
	...routineDiscoveryToolDefinitions,
] as const;

/**
 * Move the one-time tool schema conversion into module scope.
 *
 * Tool schemas are module-level constants, and their compact JSON Schema is
 * memoized per definition by `getRegisteredToolConfig`. Populating the memo is
 * not enough: `compactJsonSchema` stores the actual `z.toJSONSchema` work
 * behind lazy `input`/`output` closures, and the MCP SDK invokes those during
 * `registerTool`. This forces the exact conversions the SDK consumes (`input`
 * for each `inputSchema`, `output` for each read tool `outputSchema`) so a
 * first request only reads already-converted schemas.
 *
 * On isolate-based edge runtimes (Cloudflare Workers) module-scope work runs
 * during isolate warm-up, outside a request's billed CPU, so calling this at
 * module scope keeps the first request of a fresh isolate fast. Idempotent,
 * and a no-op after every conversion has been computed once.
 */
export function preloadHevyToolSchemas(): void {
	for (const definition of hevyToolDefinitions) {
		const config = getRegisteredToolConfig(definition);
		preloadCompactJsonSchema(config.inputSchema, "input");
		if (config.outputSchema) {
			preloadCompactJsonSchema(config.outputSchema, "output");
		}
	}
}

/** Register every Hevy tool in its production ordering. */
export function registerHevyTools(
	server: ToolRegistrar,
	runtime: ToolRuntime,
): void {
	for (const definition of hevyToolDefinitions) {
		registerToolDefinition(server, runtime, definition);
	}
}

import type { McpClientLogger } from "../utils/mcp-client-logger.js";
import type { HevyClient } from "@hevy-mcp/hevy-client";
import { createOperations, type HevyOperations } from "@hevy-mcp/operations";
import {
	HEVY_CLIENT_NOT_INITIALIZED_ERROR,
	requireClient,
} from "../utils/tool-helpers.js";
import { withErrorHandling } from "../utils/error-handler.js";
import type { ExerciseTemplateCatalog } from "../utils/exercise-template-catalog.js";
import type { McpToolResponse } from "../utils/response-contracts.js";
import type { ToolTelemetryMetadata } from "../utils/tool-taxonomy.js";
import {
	memoizeObservationScope,
	type SafeToolArgumentKey,
	type ToolObserver,
	type ToolCompletionObservation,
} from "../observation.js";
import { bucketCount, getResultTelemetry } from "../utils/result-telemetry.js";
import { resolveErrorPolicy } from "../utils/error-policy.js";
import {
	bindClientExecution,
	mergeAbortSignals,
	type ToolExecutionContext,
} from "../execution.js";
import { DEFAULT_API_TIMEOUT_MS } from "@hevy-mcp/hevy-client";
import { TELEMETRY_ARGUMENT_KEYS } from "../utils/telemetry-contract.js";
import { isBoolean, isFiniteNumber } from "../utils/type-predicates.js";

interface ArgumentKeySet {
	readonly [key: string]: true;
}

const toKeySet = (keys: readonly string[]): Readonly<ArgumentKeySet> =>
	Object.fromEntries(keys.map((key) => [key, true as const]));

const STRUCTURAL_ARGUMENT_KEYS: Readonly<ArgumentKeySet> = toKeySet(
	TELEMETRY_ARGUMENT_KEYS,
);

const PRESENCE_ARGUMENT_KEYS: Readonly<ArgumentKeySet> = {
	since: true,
	workout_id: true,
	routine_id: true,
	folder_id: true,
	exercise_template_id: true,
	date: true,
	start_date: true,
	end_date: true,
	updated_since: true,
	query: true,
	primary_muscle_group: true,
};

const NUMERIC_ARGUMENT_KEYS: Readonly<ArgumentKeySet> = {
	page: true,
	page_size: true,
	limit: true,
	offset: true,
};

const BOOLEAN_ARGUMENT_KEYS: Readonly<ArgumentKeySet> = {
	include_custom: true,
	refresh: true,
};

const structuralArgumentKeys = Object.keys(
	STRUCTURAL_ARGUMENT_KEYS,
) as SafeToolArgumentKey[];

function createSafeInvocation<TArgs extends object>(
	name: string,
	args: TArgs,
	taxonomy: ToolTelemetryMetadata | undefined,
) {
	const argumentValues = new Map<string, unknown>(Object.entries(args));
	const argumentKeys = structuralArgumentKeys.filter((key) => key in args);
	const argumentPresence: Record<string, true> = {};
	const numericArgumentBuckets: Record<
		string,
		ReturnType<typeof bucketCount>
	> = {};
	const booleanArguments: Record<string, boolean> = {};

	for (const key of argumentKeys) {
		const value = argumentValues.get(key);
		if (
			key in PRESENCE_ARGUMENT_KEYS &&
			value !== null &&
			value !== undefined
		) {
			argumentPresence[key] = true;
		}
		if (key in NUMERIC_ARGUMENT_KEYS && isFiniteNumber(value)) {
			numericArgumentBuckets[key] = bucketCount(value);
		}
		if (key in BOOLEAN_ARGUMENT_KEYS && isBoolean(value)) {
			booleanArguments[key] = value;
		}
	}

	return {
		name,
		taxonomy,
		argumentKeys,
		argumentPresence,
		numericArgumentBuckets,
		booleanArguments,
		argumentKeyCountBucket: bucketCount(Object.keys(args).length),
	};
}

export type ToolHandler<TParams extends object = object> = (
	args: TParams,
	context?: ToolExecutionContext,
) => Promise<McpToolResponse>;

export type ToolHandlerFactory = <TParams extends object>(
	fn: ToolHandler<TParams>,
	context: string,
	metadata?: ToolTelemetryMetadata,
) => ToolHandler;
export interface ToolRuntime {
	readonly client: HevyClient | null;
	readonly catalog: ExerciseTemplateCatalog;
	readonly logger?: McpClientLogger;
	readonly execution?: ToolExecutionContext;
	readonly executionTimeoutMs: number;
	readonly executionDeadline?: number;
	readonly lifecycleSignal?: AbortSignal;
	readonly operations: HevyOperations | null;
	readonly createHandler: ToolHandlerFactory;
	getClient(): HevyClient;
	getOperations(): HevyOperations;
	forExecution(context?: ToolExecutionContext): ToolRuntime;
}

export interface CreateToolRuntimeOptions {
	client: HevyClient | null;
	/** Unbound client retained across nested execution scopes. */
	baseClient?: HevyClient | null;
	operations?: HevyOperations;
	catalog: ExerciseTemplateCatalog;
	logger?: McpClientLogger;
	createHandler?: ToolHandlerFactory;
	observer?: ToolObserver;
	execution?: ToolExecutionContext;
	executionTimeoutMs?: number;
	executionDeadline?: number;
	lifecycleSignal?: AbortSignal;
}

export const defaultHandlerFactory: ToolHandlerFactory = <
	TParams extends object,
>(
	fn: ToolHandler<TParams>,
	context: string,
) => withErrorHandling(fn, context) as ToolHandler;

export function createToolRuntime({
	client,
	baseClient,
	operations,
	catalog,
	logger,
	createHandler = defaultHandlerFactory,
	observer,
	execution,
	executionTimeoutMs = DEFAULT_API_TIMEOUT_MS,
	executionDeadline,
	lifecycleSignal,
}: CreateToolRuntimeOptions): ToolRuntime {
	const rawClient = baseClient ?? client;
	const resolvedOperations =
		operations ?? (rawClient ? createOperations(rawClient) : null);
	const effectiveExecutionDeadline = executionDeadline ?? execution?.deadline;
	const createObservedHandler: ToolHandlerFactory = <TParams extends object>(
		fn: ToolHandler<TParams>,
		context: string,
		metadata?: ToolTelemetryMetadata,
	) =>
		createHandler<TParams>(
			async (args: TParams, requestContext?: ToolExecutionContext) => {
				let scope;
				try {
					scope = memoizeObservationScope(
						observer?.start(createSafeInvocation(context, args, metadata)),
					);
				} catch {
					scope = undefined;
				}
				const startedAt = Date.now();
				let handlerPromise: Promise<McpToolResponse> | undefined;
				const invokeHandler = () => {
					handlerPromise ??= Promise.resolve().then(() =>
						fn(args, requestContext),
					);
					return handlerPromise;
				};
				try {
					let runPromise: Promise<McpToolResponse>;
					if (scope) {
						try {
							runPromise = scope.run(invokeHandler);
						} catch {
							runPromise = invokeHandler();
						}
					} else {
						runPromise = invokeHandler();
					}
					const result = await runPromise.catch(invokeHandler);
					const telemetry = {
						outcome: result.isError ? "returned_error" : "success",
						durationMs: Date.now() - startedAt,
						errorOutcome: result.errorOutcome,
						result: {
							isError: Boolean(result.isError),
							hasStructuredContent: result.structuredContent !== undefined,
							contentCountBucket: bucketCount(result.content.length),
							summary: getResultTelemetry(result),
						},
					} satisfies ToolCompletionObservation;
					void scope?.finish(telemetry);
					return result;
				} catch (error) {
					const policy = resolveErrorPolicy(error, "");
					void scope?.finish({
						outcome: "thrown_error",
						durationMs: Date.now() - startedAt,
						errorType: policy.type,
						error: policy.diagnostic,
					});
					throw error;
				}
			},
			context,
			metadata,
		);
	const observedHandlerFactory = observer
		? createObservedHandler
		: createHandler;
	const runtime: ToolRuntime = {
		client,
		catalog: execution
			? {
					get: (options) => catalog.get({ ...options, execution }),
					reset: () => catalog.reset(),
				}
			: catalog,
		logger,
		execution,
		executionTimeoutMs,
		executionDeadline: effectiveExecutionDeadline,
		lifecycleSignal,
		operations: resolvedOperations,
		createHandler: observedHandlerFactory,
		getClient: () => requireClient(client),
		getOperations: () =>
			resolvedOperations ?? createOperations(requireClient(client)),
		forExecution: (nextExecution) =>
			createToolRuntime({
				client: rawClient,
				baseClient: rawClient,
				operations: resolvedOperations ?? undefined,
				catalog,
				logger,
				createHandler,
				observer,
				execution: (() => {
					const nested: {
						-readonly [
							K in keyof ToolExecutionContext
						]?: ToolExecutionContext[K];
					} = {};
					if (nextExecution) Object.assign(nested, nextExecution);
					nested.signal = mergeAbortSignals(
						lifecycleSignal,
						nextExecution?.signal,
					);
					nested.deadline =
						nextExecution?.deadline ??
						effectiveExecutionDeadline ??
						Date.now() + executionTimeoutMs;
					return nested as ToolExecutionContext;
				})(),
				executionTimeoutMs,
				executionDeadline:
					nextExecution?.deadline ?? effectiveExecutionDeadline,
				lifecycleSignal,
			}),
	};
	if (execution && client) {
		Object.assign(runtime, {
			client: bindClientExecution(requireClient(rawClient), execution),
			getClient: () => bindClientExecution(requireClient(rawClient), execution),
		});
	}
	return runtime;
}

export { HEVY_CLIENT_NOT_INITIALIZED_ERROR };

import type { McpServer, ToolAnnotations } from "@modelcontextprotocol/server";
import { z } from "zod";
import { respond, type ResponseContract } from "../utils/response-contracts.js";
import { compactJsonSchema } from "../utils/compact-json-schema.js";
import {
	createTypedToolHandler,
	type InferToolParams,
} from "../utils/tool-helpers.js";
import type { ToolTelemetryMetadata } from "../utils/tool-taxonomy.js";
import type { ToolRuntime } from "./tool-runtime.js";

type ToolDefinitionBase<
	TSchema extends Record<string, z.ZodTypeAny>,
	TResult,
> = Pick<ToolTelemetryMetadata, "feature" | "operation"> & {
	readonly name: string;
	readonly description: string;
	readonly inputSchema: TSchema;
	readonly annotations: ToolAnnotations;
	readonly responseContract: ResponseContract<TResult>;
	execute(
		runtime: ToolRuntime,
		args: InferToolParams<TSchema>,
	): Promise<TResult>;
};

type RegisteredToolConfig = {
	description: string;
	inputSchema: ReturnType<typeof compactJsonSchema>;
	annotations: ToolAnnotations;
	outputSchema?: ReturnType<typeof compactJsonSchema>;
};

export type ToolRegistrar = Pick<McpServer, "registerTool">;

export type ToolDefinition<
	TSchema extends Record<string, z.ZodTypeAny>,
	TResult,
> = ToolDefinitionBase<TSchema, TResult> &
	(
		| {
				readonly kind: "read";
				readonly outputSchema: z.ZodRawShape;
		  }
		| {
				readonly kind: "write";
				readonly outputSchema?: z.ZodRawShape;
		  }
	);

type AnyToolDefinition = ToolDefinition<Record<string, z.ZodTypeAny>, unknown>;

/**
 * One-time-per-isolate registration metadata for each tool definition.
 *
 * Building a tool's compact JSON Schema (and the SDK's eager wire conversion
 * of the `compactJsonSchema`-wrapped schema on registration) is the dominant
 * CPU cost when constructing an MCP server. Tool definitions are module-level
 * constants, so this metadata can be computed once and shared by every server
 * a single isolate builds. The SDK's `registerTool` reads the schema strictly
 * through the Standard Schema interface and never mutates it, so sharing the
 * memoized config across concurrent servers is safe.
 *
 * Keep the memo lazy: CLI and test processes that never build a Hevy server
 * pay nothing. Isolate-based edge runtimes that want the one-time conversion
 * moved into module-scope (outside request CPU) call `preloadHevyToolSchemas`.
 */
const registeredToolConfigCache = new WeakMap<
	AnyToolDefinition,
	RegisteredToolConfig
>();

export function getRegisteredToolConfig(
	definition: AnyToolDefinition,
): RegisteredToolConfig {
	const cached = registeredToolConfigCache.get(definition);
	if (cached) return cached;
	const config: RegisteredToolConfig = {
		description: definition.description,
		inputSchema: compactJsonSchema(z.strictObject(definition.inputSchema)),
		annotations: definition.annotations,
	};
	if (definition.outputSchema) {
		config.outputSchema = compactJsonSchema(z.object(definition.outputSchema));
	}
	registeredToolConfigCache.set(definition, config);
	return config;
}

export function registerToolDefinition(
	server: ToolRegistrar,
	runtime: ToolRuntime,
	definition: AnyToolDefinition,
): void {
	const directHandler = createTypedToolHandler(
		definition.inputSchema,
		async (args, requestContext) =>
			respond(
				definition.responseContract,
				await definition.execute(
					requestContext ? runtime.forExecution(requestContext) : runtime,
					args,
				),
			),
	);
	const handler = runtime.createHandler(directHandler, definition.name, {
		feature: definition.feature,
		kind: definition.kind,
		operation: definition.operation,
	});

	const config = getRegisteredToolConfig(definition);
	server.registerTool(definition.name, config, (args, context) =>
		handler(
			z.strictObject(definition.inputSchema).parse(args),
			context
				? {
						signal: context.mcpReq.signal,
						requestId: String(context.mcpReq.id),
					}
				: undefined,
		),
	);
}

import { z } from "zod";
import type {
	GetV1WorkoutsEvents200,
	PostV1Workouts201,
	PutV1WorkoutsWorkoutid200,
} from "@hevy-mcp/hevy-client/types";
import {
	paginationFields,
	nonEmptyId,
	replaceWorkoutExercisesInputFields,
	updateWorkoutInputFields,
	workoutInputFields,
} from "./input-schemas.js";
import type { ToolDefinition } from "./define-tool.js";
import type { ToolRuntime } from "./tool-runtime.js";
import {
	createWorkoutResponse,
	updateWorkoutResponse,
	workoutEventsResponse,
	workoutResponse,
	workoutsResponse,
} from "../utils/response-contracts.js";
import {
	createAnnotations,
	readOnlyAnnotations,
	updateAnnotations,
} from "../utils/tool-annotations.js";
import { WORKOUT_PUT_REQUIRES_IS_PRIVATE } from "./hevy-quirks.js";

import type { InferToolParams } from "../utils/tool-helpers.js";
import { buildWorkoutUpdatePayload } from "./mutation-semantics.js";
import { isExpectedListPageNotFound } from "../utils/hevy-error-policy.js";

const getWorkoutsSchema = paginationFields({
	defaultPageSize: 5,
	maxPageSize: 10,
	integerPage: false,
});
type GetWorkoutsParams = InferToolParams<typeof getWorkoutsSchema>;

const getWorkoutSchema = { workout_id: nonEmptyId } as const;
type GetWorkoutParams = InferToolParams<typeof getWorkoutSchema>;

const getWorkoutEventsSchema = {
	...paginationFields({ defaultPageSize: 5, maxPageSize: 10 }),
	since: z.string().default("1970-01-01T00:00:00Z"),
} as const;
type GetWorkoutEventsParams = InferToolParams<typeof getWorkoutEventsSchema>;

const createWorkoutSchema = workoutInputFields;
type CreateWorkoutParams = InferToolParams<typeof createWorkoutSchema>;

const updateWorkoutSchema = updateWorkoutInputFields;
type UpdateWorkoutParams = InferToolParams<typeof updateWorkoutSchema>;

const replaceWorkoutExercisesSchema = replaceWorkoutExercisesInputFields;
type ReplaceWorkoutExercisesParams = InferToolParams<
	typeof replaceWorkoutExercisesSchema
>;

export const workoutToolDefinitions = [
	{
		name: "get-workouts",
		feature: "workouts" as const,
		operation: "list" as const,
		description:
			"Read-only. Lists compact workout summaries in Hevy API pagination order, not sorted by workout start_time. Use get-workout for exercises and sets; results are paginated.",
		inputSchema: getWorkoutsSchema,
		outputSchema: workoutsResponse.outputSchema,
		annotations: readOnlyAnnotations("Get Workouts"),
		kind: "read" as const,
		responseContract: workoutsResponse,
		execute: async (runtime: ToolRuntime, args: GetWorkoutsParams) => {
			const data = await runtime.getOperations().workouts.list.execute(
				{
					page: args.page,
					pageSize: args.page_size,
				},
				runtime.execution,
			);
			return data;
		},
	},
	{
		name: "get-workout",
		feature: "workouts" as const,
		operation: "get" as const,
		description:
			"Read-only. Gets one workout with exercises and sets by workout_id. Use get-workouts to discover IDs.",
		inputSchema: getWorkoutSchema,
		outputSchema: workoutResponse.outputSchema,
		annotations: readOnlyAnnotations("Get Workout"),
		kind: "read" as const,
		responseContract: workoutResponse,
		execute: async (runtime: ToolRuntime, args: GetWorkoutParams) => {
			const data = await runtime
				.getOperations()
				.workouts.get.execute(
					{ workoutId: args.workout_id },
					runtime.execution,
				);
			return { ...data, workout_id: args.workout_id };
		},
	},
	{
		name: "get-workout-events",
		feature: "workouts" as const,
		operation: "sync" as const,
		description:
			"Read-only. Lists workout update and deletion events since a timestamp for incremental sync; results are paginated.",
		inputSchema: getWorkoutEventsSchema,
		outputSchema: workoutEventsResponse.outputSchema,
		annotations: readOnlyAnnotations("Get Workout Events"),
		kind: "read" as const,
		responseContract: workoutEventsResponse,
		execute: async (runtime: ToolRuntime, args: GetWorkoutEventsParams) => {
			try {
				const data: GetV1WorkoutsEvents200 = await runtime
					.getClient()
					.getWorkoutEvents({
						page: args.page,
						pageSize: args.page_size,
						since: args.since,
					});
				return {
					events: data?.events,
					since: args.since,
					page: args.page,
					pageCount: data?.page_count,
				};
			} catch (error) {
				if (isExpectedListPageNotFound(error, args.page)) {
					return {
						events: [],
						since: args.since,
						page: args.page,
